insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Three Chord Un-Edited","rar":"shelf","f":"Three Chord","x":"Un-Edited","p":118.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":true,"fin":null,"msrp":null,"core":true,"al2":[],"img":"https://threechordbourbon.com/wp-content/uploads/Un-edited.jpg","u":"https://threechordbourbon.com/our-whiskey/","pr":"Three Chord","mk":"aeee5145-00c4-449d-acc5-2454cef6ca4c"},{"n":"Three Chord Backstage Series: The Cadillac Three","rar":"limited","f":"Three Chord","x":"Backstage Series: The Cadillac Three","p":90.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"other","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://threechordbourbon.com/wp-content/uploads/three-chord-bourbon-the-cadillac-three-wide-1.png","u":"https://threechordbourbon.com/backstage-series/","pr":"Three Chord","mk":"aeee5145-00c4-449d-acc5-2454cef6ca4c"},{"n":"Three Chord Backstage Series: Goodbye June","rar":"limited","f":"Three Chord","x":"Backstage Series: Goodbye June","p":120.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":true,"fin":"Cherry Bounce Barrels","msrp":null,"core":false,"al2":[],"img":"https://threechordbourbon.com/wp-content/uploads/goodbye-june-wide-1-1.png","u":"https://threechordbourbon.com/backstage-series/","pr":"Three Chord","mk":"aeee5145-00c4-449d-acc5-2454cef6ca4c"},{"n":"Three Chord Backstage Series: Lucero","rar":"limited","f":"Three Chord","x":"Backstage Series: Lucero","p":98.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"tennessee","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://threechordbourbon.com/wp-content/uploads/lucero-wide.png","u":"https://threechordbourbon.com/backstage-series/","pr":"Three Chord","mk":"aeee5145-00c4-449d-acc5-2454cef6ca4c"},{"n":"Three Chord Backstage Series: Theory of a Deadman","rar":"limited","f":"Three Chord","x":"Backstage Series: Theory of a Deadman","p":93.4,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":false,"al2":[],"img":"https://threechordbourbon.com/wp-content/uploads/NEW_THEORYOFDEADMAN_Wide.png","u":"https://threechordbourbon.com/backstage-series/","pr":"Three Chord","mk":"aeee5145-00c4-449d-acc5-2454cef6ca4c"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
